async function load(){
  if(!promise)promise=(async()=>{
    const response=await fetch('./data/lie-group-lessons.json?v=20261113-depth1');
    if(!response.ok)throw Error(`Lie group Course failed to load (HTTP ${response.status}）。`);
    const data=await response.json();
    if(!Array.isArray(data.lessons)||!data.lessons.length||data.lessons.some(lesson=>!lesson.id||!Array.isArray(lesson.quiz)||lesson.quiz.some(q=>!Array.isArray(q.choices)||!Number.isInteger(q.answer)||q.answer<0||q.answer>=q.choices.length)))throw Error("Lie group The course data is incomplete, please reload.");
    const valid={};for(const {quiz,key} of entries(data.lessons)){const item=state.answers[key];if(item&&Number.isInteger(item.selected)&&item.selected>=0&&item.selected<quiz.choices.length&&typeof item.checked==='boolean')valid[key]={selected:item.selected,checked:item.checked};}
    state.answers=valid;loaded=data;return data;
  })().catch(error=>{promise=null;throw error;});return promise;
}
